import React from 'react';
import { Home, Folder, Settings } from 'lucide-react'; // иконки из lucide-react

const Sidebar = () => {
  return (
    <aside className="w-64 bg-white border-r shadow-md h-full">
      <div className="p-6 text-2xl font-bold text-purple-600 border-b">
        MyApp
      </div>
      <nav className="p-4 space-y-2">
        <SidebarLink href="#" icon={<Home size={18} />} label="Dashboard" />
        <SidebarLink href="#" icon={<Folder size={18} />} label="Projects" />
        <SidebarLink href="#" icon={<Settings size={18} />} label="Settings" />
      </nav>
    </aside>
  );
};

const SidebarLink = ({
  href,
  icon,
  label,
}: {
  href: string;
  icon: React.ReactNode;
  label: string;
}) => {
  return (
    <a
      href={href}
      className="flex items-center gap-3 px-4 py-2 rounded-md text-gray-700 hover:bg-purple-100 hover:text-purple-700 transition-colors duration-200"
    >
      {icon}
      <span>{label}</span>
    </a>
  );
};

export default Sidebar;
